// Package style manages style profiles: "what a slide should look like",
// captured by keeping real, working cues copied out of one of your own .pro
// files plus a few settings (colors, forced caps, Audience Look UUIDs).
//
// New slides are generated by cloning a template cue and swapping only the
// text, so fonts, box position and size, background, shadow and everything
// else come straight from the example - nothing has to be described by hand.
//
// Profiles are stored as JSON, one file per style, in the same format the
// original Python toolkit used, so existing style files load unchanged.
package style

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"google.golang.org/protobuf/proto"

	"github.com/thatguycleeb/propresenter-toolkit/internal/pb"
)

// Kind is the conversion mode a style is for.
type Kind string

const (
	KindPrompts Kind = "prompts" // one reflowing text box, template role "body"
	KindSlides  Kind = "slides"  // title / point / keyword / scripture templates
)

// Template and look roles.
const (
	RoleBody      = "body"
	RoleTitle     = "title"
	RolePoint     = "point"
	RoleKeyword   = "keyword"
	RoleScripture = "scripture"
	RoleBackTo    = "backto" // look only: used on "Back to X" duplicate slides
)

// RequiredRoles lists the template roles a style of this kind must have.
func (k Kind) RequiredRoles() []string {
	if k == KindPrompts {
		return []string{RoleBody}
	}
	return []string{RoleTitle, RolePoint, RoleKeyword, RoleScripture}
}

// Look identifies an Audience Look by the UUID and name ProPresenter uses.
type Look struct {
	UUID string `json:"uuid"`
	Name string `json:"name"`
}

// Settings are the knobs layered on top of the template cues.
type Settings struct {
	RegularColor  string          `json:"regular_color,omitempty"`
	EmphasisColor string          `json:"emphasis_color,omitempty"`
	ForceCapsOff  *bool           `json:"force_caps_off,omitempty"`
	AudienceLooks map[string]Look `json:"audience_looks,omitempty"`
}

// Regular returns the normal text color, defaulting to white.
func (s Settings) Regular() string { return orDefault(s.RegularColor, "#FFFFFF") }

// Emphasis returns the highlight color for bold words, defaulting to yellow.
func (s Settings) Emphasis() string { return orDefault(s.EmphasisColor, "#FFFF00") }

// CapsOff reports whether forced ALL CAPS should be stripped from the
// template (default true), so the PDF's own casing is kept.
func (s Settings) CapsOff() bool { return s.ForceCapsOff == nil || *s.ForceCapsOff }

// Profile is one saved style.
type Profile struct {
	Name      string            `json:"name"`
	Kind      Kind              `json:"kind"`
	Templates map[string][]byte `json:"templates"` // role -> serialized rv.data.Cue (base64 in JSON)
	Settings  Settings          `json:"settings"`
}

// TemplateCue returns a fresh, independent copy of the template for role.
func (p *Profile) TemplateCue(role string) (*pb.Cue, error) {
	raw, ok := p.Templates[role]
	if !ok {
		return nil, fmt.Errorf("style %q has no %q template", p.Name, role)
	}
	cue := &pb.Cue{}
	if err := proto.Unmarshal(raw, cue); err != nil {
		return nil, fmt.Errorf("style %q: bad %q template: %w", p.Name, role, err)
	}
	return cue, nil
}

// Missing returns the required template roles this profile lacks.
func (p *Profile) Missing() []string {
	var out []string
	for _, r := range p.Kind.RequiredRoles() {
		if _, ok := p.Templates[r]; !ok {
			out = append(out, r)
		}
	}
	return out
}

// Roles returns the captured template roles in a stable order.
func (p *Profile) Roles() []string {
	var out []string
	for r := range p.Templates {
		out = append(out, r)
	}
	sort.Strings(out)
	return out
}

// Parse decodes a profile from JSON.
func Parse(data []byte) (*Profile, error) {
	var p Profile
	if err := json.Unmarshal(data, &p); err != nil {
		return nil, err
	}
	if p.Name == "" {
		return nil, errors.New("style has no name")
	}
	if p.Kind != KindPrompts && p.Kind != KindSlides {
		return nil, fmt.Errorf("style %q has unknown kind %q", p.Name, p.Kind)
	}
	return &p, nil
}

// JSON encodes the profile the way it is stored on disk.
func (p *Profile) JSON() ([]byte, error) {
	return json.MarshalIndent(p, "", "  ")
}

func orDefault(s, def string) string {
	if strings.TrimSpace(s) == "" {
		return def
	}
	return s
}

// ----------------------------------------------------------------- Store --

// Store is a folder of style profiles, one "<name>.json" per style.
type Store struct {
	Dir string
}

// List returns every readable profile, sorted by name. Unreadable files
// are skipped rather than breaking the whole list.
func (s Store) List() ([]*Profile, error) {
	entries, err := os.ReadDir(s.Dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var out []*Profile
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		p, err := s.Load(strings.TrimSuffix(e.Name(), ".json"))
		if err != nil {
			continue
		}
		out = append(out, p)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// ListKind returns the names of profiles of one kind.
func (s Store) ListKind(k Kind) ([]string, error) {
	all, err := s.List()
	if err != nil {
		return nil, err
	}
	var names []string
	for _, p := range all {
		if p.Kind == k {
			names = append(names, p.Name)
		}
	}
	return names, nil
}

// Load reads one profile by name.
func (s Store) Load(name string) (*Profile, error) {
	path, err := s.path(name)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return Parse(data)
}

// Save writes a profile, replacing any existing one with the same name.
func (s Store) Save(p *Profile) error {
	path, err := s.path(p.Name)
	if err != nil {
		return err
	}
	data, err := p.JSON()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(s.Dir, 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// Delete removes a profile.
func (s Store) Delete(name string) error {
	path, err := s.path(name)
	if err != nil {
		return err
	}
	return os.Remove(path)
}

// path maps a style name to its file, refusing names that could escape Dir.
func (s Store) path(name string) (string, error) {
	name = strings.TrimSpace(name)
	if name == "" || strings.ContainsAny(name, `/\:*?"<>|`) || name == "." || name == ".." {
		return "", fmt.Errorf("invalid style name %q (avoid / \\ : * ? \" < > |)", name)
	}
	return filepath.Join(s.Dir, name+".json"), nil
}

// Seed copies the given default profiles into the store if it holds no
// styles yet, so a fresh install starts with working examples.
func (s Store) Seed(defaults map[string][]byte) error {
	existing, err := s.List()
	if err != nil {
		return err
	}
	if len(existing) > 0 {
		return nil
	}
	for _, data := range defaults {
		p, err := Parse(data)
		if err != nil {
			return err
		}
		if err := s.Save(p); err != nil {
			return err
		}
	}
	return nil
}
